import json

def review(action, evidence, call_reviewer):
    raw = call_reviewer(action, evidence)   # the guardrail model's reply
    try:
        verdict = json.loads(raw)["decision"]  # expects {"decision": "allow" | "deny"}
    except (ValueError, KeyError, TypeError):
        return {"decision": "deny", "reason": "review_failed"}   # fail closed
    if verdict not in ("allow", "deny"):
        return {"decision": "deny", "reason": "review_failed"}
    return {"decision": verdict, "reason": "reviewed"}

# Count reason="review_failed" apart from reason="reviewed",
# or "blocked" quietly means two different things.
